import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const SCHEMA = `
CREATE TABLE IF NOT EXISTS jobs (
  seq             INTEGER PRIMARY KEY AUTOINCREMENT,
  id              TEXT NOT NULL UNIQUE,
  status          TEXT NOT NULL CHECK (status IN ('queued', 'running', 'completed', 'failed')),
  input           TEXT NOT NULL,
  steps           INTEGER NOT NULL,
  fail_attempts   INTEGER NOT NULL,
  attempts        INTEGER NOT NULL DEFAULT 0,
  completed_steps INTEGER NOT NULL DEFAULT 0,
  output          TEXT,
  error           TEXT,
  run_after       INTEGER NOT NULL DEFAULT 0,
  created_at      TEXT NOT NULL,
  updated_at      TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS jobs_queue ON jobs (status, run_after, seq);
CREATE TABLE IF NOT EXISTS idempotency_keys (
  key         TEXT PRIMARY KEY,
  fingerprint TEXT NOT NULL,
  job_id      TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS heartbeats (
  name TEXT PRIMARY KEY,
  at   INTEGER NOT NULL
);
`;

/** Opens the SQLite database shared by the server and worker processes, creating the schema if needed. */
export function openDatabase(path: string = process.env.DATABASE_PATH || 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
  db.exec(SCHEMA);
  return db;
}
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import { JobStore } from './store.ts';
import { MAX_BODY_BYTES, parseSubmission, type FieldError } from './validate.ts';

const db = openDatabase();
const store = new JobStore(db);
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function sendJson(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  sendJson(res, status, { error: fields ? { code, message, fields } : { code, message } });
}

const notFound = (res: ServerResponse) => sendError(res, 404, 'not_found', 'No such resource.');
const methodNotAllowed = (req: IncomingMessage, res: ServerResponse) => {
  req.resume();
  sendError(res, 405, 'method_not_allowed', `${req.method} is not allowed here.`);
};

/** Reads the body, or resolves to null when it is larger than MAX_BODY_BYTES. */
function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size <= MAX_BODY_BYTES) chunks.push(chunk);
      else tooLarge = true;
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const body = await readBody(req);
  const rawKey = req.headers['idempotency-key'];
  const parsed = parseSubmission(req.headers['content-type'], body, typeof rawKey === 'string' ? rawKey : undefined);
  if (!parsed.ok) {
    sendError(res, 400, 'invalid_request', 'The submission is invalid.', parsed.fields);
    return;
  }
  const { value, key } = parsed;
  const fingerprint = JSON.stringify([value.input, value.steps, value.failAttempts]);
  const outcome = store.createJob(value, key === undefined ? undefined : { key, fingerprint });
  if (outcome.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  sendJson(res, outcome.kind === 'created' ? 201 : 200, outcome.job);
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed(req, res);
    sendJson(res, 200, { status: 'ok', worker: store.workerUp(Date.now()) ? 'up' : 'down' });
    return;
  }

  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(req, res);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (pathname === '/api/jobs') {
    if (method === 'GET') return sendJson(res, 200, { jobs: store.listJobs() });
    if (method === 'POST') return handleCreate(req, res);
    return methodNotAllowed(req, res);
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(req, res);
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return notFound(res);
    }
    const job = store.getJob(id);
    return job ? sendJson(res, 200, job) : notFound(res);
  }

  req.resume();
  notFound(res);
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);
import type { DatabaseSync } from 'node:sqlite';
import { randomUUID } from 'node:crypto';

/** A job runs at most this many times in total (the first attempt plus two retries). */
export const MAX_ATTEMPTS = 3;
/** The worker counts as up if its heartbeat is at most this old. */
export const HEARTBEAT_STALE_MS = 3000;

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** The public job shape returned by every endpoint that returns a job. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

interface JobRow {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed_steps: number;
  output: string | null;
  error: string | null;
  created_at: string;
  updated_at: string;
}

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

export type CreateOutcome =
  | { kind: 'created'; job: Job }
  | { kind: 'replayed'; job: Job }
  | { kind: 'conflict' };

function toJob(r: JobRow): Job {
  return {
    id: r.id,
    status: r.status,
    input: r.input,
    steps: r.steps,
    failAttempts: r.fail_attempts,
    attempts: r.attempts,
    progress: { completed: r.completed_steps, total: r.steps },
    result: r.status === 'completed' ? { output: r.output ?? '' } : null,
    error: r.status === 'failed' ? (r.error ?? 'transient failure') : null,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

/** All reads and writes of job state. Used by both the server and the worker. */
export class JobStore {
  constructor(private readonly db: DatabaseSync) {}

  /** Runs `fn` inside a write transaction. BEGIN IMMEDIATE takes the write lock up front. */
  private tx<T>(fn: () => T): T {
    this.db.exec('BEGIN IMMEDIATE');
    try {
      const result = fn();
      this.db.exec('COMMIT');
      return result;
    } catch (e) {
      this.db.exec('ROLLBACK');
      throw e;
    }
  }

  private jobRow(id: string): JobRow | undefined {
    return this.db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow | undefined;
  }

  getJob(id: string): Job | undefined {
    const row = this.jobRow(id);
    return row && toJob(row);
  }

  /** Newest first. */
  listJobs(): Job[] {
    return (this.db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[]).map(toJob);
  }

  /** Creates a job. With an idempotency key, a replay returns the original job and a mismatch is a conflict. */
  createJob(job: NewJob, idempotency?: { key: string; fingerprint: string }): CreateOutcome {
    return this.tx<CreateOutcome>(() => {
      if (idempotency) {
        const prior = this.db
          .prepare('SELECT fingerprint, job_id FROM idempotency_keys WHERE key = ?')
          .get(idempotency.key) as unknown as { fingerprint: string; job_id: string } | undefined;
        if (prior) {
          if (prior.fingerprint !== idempotency.fingerprint) return { kind: 'conflict' };
          const existing = this.getJob(prior.job_id);
          if (existing) return { kind: 'replayed', job: existing };
        }
      }
      const id = randomUUID();
      const now = new Date().toISOString();
      this.db
        .prepare(
          `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed_steps, output, error, run_after, created_at, updated_at)
           VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, 0, ?, ?)`,
        )
        .run(id, job.input, job.steps, job.failAttempts, now, now);
      if (idempotency) {
        this.db
          .prepare('INSERT INTO idempotency_keys (key, fingerprint, job_id) VALUES (?, ?, ?)')
          .run(idempotency.key, idempotency.fingerprint, id);
      }
      return { kind: 'created', job: this.getJob(id) as Job };
    });
  }

  /** Takes the oldest queued job that is due, marks it running and counts the new attempt. */
  claimNext(now: number): Job | undefined {
    return this.tx(() => {
      const row = this.db
        .prepare(`SELECT id FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1`)
        .get(now) as unknown as { id: string } | undefined;
      if (!row) return undefined;
      this.db
        .prepare(`UPDATE jobs SET status = 'running', attempts = attempts + 1, completed_steps = 0, updated_at = ? WHERE id = ?`)
        .run(new Date().toISOString(), row.id);
      return this.getJob(row.id);
    });
  }

  setProgress(id: string, completed: number): void {
    this.db
      .prepare(`UPDATE jobs SET completed_steps = ?, updated_at = ? WHERE id = ? AND status = 'running'`)
      .run(completed, new Date().toISOString(), id);
  }

  /** Puts a failed attempt back in the queue, due at `runAfter` (epoch ms). */
  scheduleRetry(id: string, runAfter: number): void {
    this.db
      .prepare(`UPDATE jobs SET status = 'queued', completed_steps = 0, run_after = ?, updated_at = ? WHERE id = ? AND status = 'running'`)
      .run(runAfter, new Date().toISOString(), id);
  }

  completeJob(id: string, output: string): void {
    this.db
      .prepare(
        `UPDATE jobs SET status = 'completed', output = ?, error = NULL, completed_steps = steps, updated_at = ?
         WHERE id = ? AND status = 'running'`,
      )
      .run(output, new Date().toISOString(), id);
  }

  failJob(id: string, error: string): void {
    this.db
      .prepare(`UPDATE jobs SET status = 'failed', output = NULL, error = ?, updated_at = ? WHERE id = ? AND status = 'running'`)
      .run(error, new Date().toISOString(), id);
  }

  /**
   * Returns a running job to the queue because its attempt was interrupted (worker stopped or killed).
   * The interrupted attempt is not counted, so the job's next attempt uses the same number.
   * Returns the number of jobs requeued.
   */
  requeueRunning(): number {
    const result = this.db
      .prepare(
        `UPDATE jobs SET status = 'queued', attempts = attempts - 1, completed_steps = 0, run_after = 0, updated_at = ?
         WHERE status = 'running'`,
      )
      .run(new Date().toISOString());
    return Number(result.changes);
  }

  interrupt(id: string): void {
    this.db
      .prepare(
        `UPDATE jobs SET status = 'queued', attempts = attempts - 1, completed_steps = 0, run_after = 0, updated_at = ?
         WHERE id = ? AND status = 'running'`,
      )
      .run(new Date().toISOString(), id);
  }

  heartbeat(now: number): void {
    this.db
      .prepare(`INSERT INTO heartbeats (name, at) VALUES ('worker', ?) ON CONFLICT(name) DO UPDATE SET at = excluded.at`)
      .run(now);
  }

  clearHeartbeat(): void {
    this.db.prepare(`DELETE FROM heartbeats WHERE name = 'worker'`).run();
  }

  workerUp(now: number): boolean {
    const row = this.db.prepare(`SELECT at FROM heartbeats WHERE name = 'worker'`).get() as unknown as { at: number } | undefined;
    return row !== undefined && now - row.at <= HEARTBEAT_STALE_MS;
  }
}
export interface FieldError {
  field: string;
  message: string;
}

export interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
}

export type ParseResult =
  | { ok: true; value: Submission; key: string | undefined }
  | { ok: false; fields: FieldError[] };

/** Largest request body accepted for a submission, in bytes. */
export const MAX_BODY_BYTES = 16 * 1024;

const IDEMPOTENCY_KEY = /^[A-Za-z0-9_-]{1,128}$/;
const KNOWN_FIELDS = new Set(['input', 'steps', 'failAttempts']);

const isPlainObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);

/**
 * Validates a `POST /api/jobs` request. `body` is the raw body text, or null when it exceeded
 * MAX_BODY_BYTES. Every problem is reported, not just the first.
 */
export function parseSubmission(contentType: string | undefined, body: string | null, idempotencyKey: string | undefined): ParseResult {
  const fields: FieldError[] = [];

  const mediaType = (contentType ?? '').split(';')[0]!.trim().toLowerCase();
  if (mediaType !== 'application/json') fields.push({ field: 'body', message: 'Content-Type must be application/json' });

  let data: Record<string, unknown> | undefined;
  if (body === null) {
    fields.push({ field: 'body', message: `body must be at most ${MAX_BODY_BYTES} bytes` });
  } else {
    let parsed: unknown;
    let isJson = true;
    try {
      parsed = JSON.parse(body);
    } catch {
      isJson = false;
      fields.push({ field: 'body', message: 'body must be valid JSON' });
    }
    if (isJson) {
      if (isPlainObject(parsed)) data = parsed;
      else fields.push({ field: 'body', message: 'body must be a JSON object' });
    }
  }

  if (data) {
    for (const name of Object.keys(data)) {
      if (!KNOWN_FIELDS.has(name)) fields.push({ field: name, message: 'unknown field' });
    }
  }

  let input = '';
  if (data) {
    if (!Object.hasOwn(data, 'input')) {
      fields.push({ field: 'input', message: 'input is required' });
    } else if (typeof data.input !== 'string') {
      fields.push({ field: 'input', message: 'input must be a string' });
    } else if (data.input.length < 1 || data.input.length > 1000) {
      fields.push({ field: 'input', message: 'input must be 1 to 1000 characters' });
    } else if (data.input.trim() === '') {
      fields.push({ field: 'input', message: 'input must not be blank' });
    } else {
      input = data.input;
    }
  }

  const integer = (name: string, min: number, max: number, fallback: number): number => {
    if (!data || !Object.hasOwn(data, name)) return fallback;
    const v = data[name];
    if (typeof v !== 'number' || !Number.isInteger(v) || v < min || v > max) {
      fields.push({ field: name, message: `${name} must be an integer from ${min} to ${max}` });
      return fallback;
    }
    return v;
  };
  const steps = integer('steps', 1, 20, 5);
  const failAttempts = integer('failAttempts', 0, 5, 0);

  let key: string | undefined;
  if (idempotencyKey !== undefined) {
    if (IDEMPOTENCY_KEY.test(idempotencyKey)) key = idempotencyKey;
    else fields.push({ field: 'Idempotency-Key', message: 'Idempotency-Key must be 1 to 128 characters of letters, digits, "_" or "-"' });
  }

  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, value: { input, steps, failAttempts }, key };
}
import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import { JobStore, MAX_ATTEMPTS, type Job } from './store.ts';

const STEP_MS = 100;
const POLL_MS = 200;
const RETRY_DELAY_MS = 500;
const HEARTBEAT_MS = 1000;

const db = openDatabase();
const store = new JobStore(db);

let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

// A previous worker that died mid-attempt left jobs as "running". Requeue them: they run again.
const requeued = store.requeueRunning();
if (requeued > 0) console.log(`requeued ${requeued} interrupted job(s)`);

store.heartbeat(Date.now());
const heartbeat = setInterval(() => store.heartbeat(Date.now()), HEARTBEAT_MS);

/** Runs one attempt of a job. The attempt number is `job.attempts`, already counted when claimed. */
async function runAttempt(job: Job): Promise<void> {
  const attempt = job.attempts;
  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) {
      store.interrupt(job.id);
      return;
    }
    if (attempt <= job.failAttempts) {
      // Simulated transient failure: it happens at the first step, before any progress.
      if (attempt < MAX_ATTEMPTS) store.scheduleRetry(job.id, Date.now() + RETRY_DELAY_MS);
      else store.failJob(job.id, 'transient failure');
      return;
    }
    store.setProgress(job.id, step);
  }
  store.completeJob(job.id, job.input.toUpperCase());
}

console.log('worker started');
while (!stopping) {
  const job = store.claimNext(Date.now());
  if (!job) {
    await sleep(POLL_MS);
    continue;
  }
  await runAttempt(job);
}

clearInterval(heartbeat);
store.clearHeartbeat();
db.close();
console.log('worker stopped');
