<body>
  <h1>Job tracker</h1>

  <form data-testid="job-form" id="job-form" novalidate>
    <label>Input
      <input data-testid="job-input" name="input" type="text" autocomplete="off">
    </label>
    <label>Steps
      <input data-testid="job-steps" name="steps" type="number" step="any" placeholder="5">
    </label>
    <label>Fail attempts
      <input data-testid="job-fail-attempts" name="failAttempts" type="number" step="any" placeholder="0">
    </label>
    <button data-testid="job-submit" type="submit">Submit</button>
  </form>

  <div data-testid="form-error" role="alert"></div>

  <ul data-testid="job-list" id="job-list"></ul>

  <script>
    (() => {
      const form = document.getElementById('job-form');
      const inputEl = document.querySelector('[data-testid="job-input"]');
      const stepsEl = document.querySelector('[data-testid="job-steps"]');
      const failEl = document.querySelector('[data-testid="job-fail-attempts"]');
      const submitEl = document.querySelector('[data-testid="job-submit"]');
      const errorEl = document.querySelector('[data-testid="form-error"]');
      const list = document.querySelector('[data-testid="job-list"]');

      // Numeric fields are sent as numbers. Anything else is sent as typed, so the API can reject it.
      function numericOrUndefined(text) {
        const s = text.trim();
        if (s === '') return undefined;
        const n = Number(s);
