      }

      function updateRow(li, job) {
        li.querySelector('[data-testid="job-status"]').textContent = job.status;
        li.querySelector('[data-testid="job-progress"]').textContent = `${job.progress.completed}/${job.progress.total}`;
        let text = '';
        if (job.status === 'completed' && job.result) text = job.result.output;
        else if (job.status === 'failed') text = job.error || '';
        li.querySelector('[data-testid="job-result"]').textContent = text;
        li.querySelector('.input').textContent = job.input;
      }

      async function refresh() {
        let jobs;
        try {
          const res = await fetch('/api/jobs', { headers: { accept: 'application/json' } });
          if (!res.ok) return;
          ({ jobs } = await res.json());
        } catch {
